  -- Patrick J. Ahrens / housing  (was 3, season 2)
UPDATE inform.politician_context SET reasoning = 'Blanked 2026-10-08 (migration 1908). 🔴🔴 THE EVIDENCE DESCRIBES A DIFFERENT PERSON. This row is State Senator Benjamin Allen''s research filed under Assembly Member Patrick J. Ahrens. The rows cite sd24.senate.ca.gov, a Senate district site, and credit Ahrens with AUTHORING Senate bills -- SB 54 (Plastic Pollution Prevention Act), SB 867 (the $10B climate bond), SB 1444 (South Bay Regional Housing Trust), SB 933/777/916 (arts education), SB 277 (the personal-belief vaccine exemption repeal) and SB 450 -- plus SCA 2 of 2021-22. 🔑 TWO DECISIVE TESTS, NEITHER NEEDING A PAGE: this database''s own rows credit SB 1444 and SB 867 to Senator Benjamin Allen; and Ahrens was first elected to the Assembly in 2024, so he cannot have authored a 2021-22 constitutional amendment. The chair being removed is 3, read from Season 2. A chair must rest on evidence about the person it is shown under, so there is nothing here to keep and the spoke is left empty. ⚠ THIS IS NOT A JUDGEMENT THAT THE MEMBER HAS NO POSITION -- it is that this row never contained their evidence. Re-research from their own record is owed. The sources examined are kept below so the next reader does not derive this again from scratch.', sources = ARRAY['https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202120220SCA2']::text[], updated_at = now()
 WHERE season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND politician_id = 'bd4dc076-4bdd-4e10-be2c-80d998b17c50'::uuid AND topic_id = '669cac97-66a6-4087-b036-936fbe62efb3'::uuid;
UPDATE inform.politician_answers SET value = 0, updated_at = now()
 WHERE season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND politician_id = 'bd4dc076-4bdd-4e10-be2c-80d998b17c50'::uuid AND topic_id = '669cac97-66a6-4087-b036-936fbe62efb3'::uuid;


DO $post$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context
   WHERE season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'
     AND reasoning LIKE '%(migration 1908)%';
  IF n <> 47 THEN
    RAISE EXCEPTION 'migration 1908: wrote % reasoning rows, expected 47', n;
  END IF;

  -- every row written must be at 0, and must have an answer row
  SELECT count(*) INTO n
    FROM inform.politician_context c
    JOIN inform.politician_answers a ON a.politician_id = c.politician_id
     AND a.topic_id = c.topic_id AND a.season_id = c.season_id
   WHERE c.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'
     AND c.reasoning LIKE '%(migration 1908)%' AND a.value = 0;
  IF n <> 47 THEN
    RAISE EXCEPTION 'migration 1908: % of 47 rows are blanked with an answer row, expected 47', n;
  END IF;

  -- Season 1 must be untouched
  SELECT count(*) INTO n FROM inform.politician_context
   WHERE season_id = '2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3'
     AND reasoning LIKE '%migration 1908%';
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1908: % Season 1 rows were altered, expected 0', n;
  END IF;

  -- 🔑 THE ROWS THAT ARE *NOT* CONTAMINATED MUST SURVIVE. Catherine Stefani's immigration row is
  -- genuinely about her despite carrying an sd22 citation, and every vote-based row for these
  -- eight members is their own. If this migration had blanked by PERSON rather than by ROW,
  -- this count would collapse.
  SELECT count(*) INTO n
    FROM inform.politician_answers a
    JOIN inform.seasons s ON s.id = a.season_id
    JOIN essentials.politicians p ON p.id = a.politician_id
   WHERE s.number IN (1,2) AND a.value > 0
     AND p.full_name IN ('Alexandra M. Macedo','Patrick J. Ahrens','Dr. Corey A. Jackson',
                         'James C. Ramos','Phillip Chen','Gregg Hart','Catherine Stefani');
  IF n < 40 THEN
    RAISE EXCEPTION 'migration 1908: only % live rows left across the seven mixed members -- this file should have blanked by ROW, not by PERSON', n;
  END IF;
END
$post$;
